class stringx {
    char *data;

public:
    stringx &operator=(const stringx &);
    ~stringx();
};

class Font {
public:
    enum HORIZJUST {
        HORIZJUST_LEFT,
        HORIZJUST_CENTER,
        HORIZJUST_RIGHT
    };
    enum VERTJUST {
        VERTJUST_TOP,
        VERTJUST_CENTER,
        VERTJUST_BOTTOM
    };
};

class color32 {
    unsigned char red;
    unsigned char green;
    unsigned char blue;
    unsigned char alpha;

public:
    unsigned char get_alpha() const { return alpha; }
    void set_alpha(unsigned char value) { alpha = value; }
};

template <class T>
void adjustCoords(T &, T &);

class TextString {
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;

protected:
    void cons(Font *f, stringx t, float x1, float y1, int z1, float s,
              Font::HORIZJUST horizJust, Font::VERTJUST vertJust,
              bool no_col, color32 col);
};

void TextString::cons(Font* f, stringx t, float x1, float y1, int z1, float s, const Font::HORIZJUST horizJust, const Font::VERTJUST vertJust, bool no_col, color32 col)
{
	font = f;
	text = t;
	x = x1;
	y = y1;
	adjustCoords(x, y);
	z = z1;
	scale = s;
	hJustify = horizJust;
	vJustify = vertJust;
	checkTime = false;
	time = 1.0f;
	even_number_spacing = true;
	no_color = no_col;
	color = col;
	if(color.get_alpha() == 0)
		color.set_alpha(255);
	fade = 0;
	button_scale = -1;
	override_alpha = false;
}
